// src/scenes/FirstScene.ts
import { Scene, Circle, Rect, Color, Create, Morph, Rate, RIGHT, UP } from "retiam";

export class FirstScene extends Scene {
    public async run() {
        // Set background color
        this.clearColor(new Color(0.05, 0.05, 0.1, 1.0));

        // Create a 2D Circle Primitive
        const circle = new Circle(2.0);
        circle.paint.fill = new Color(0.0, 0.8, 1.0, 1.0);
        circle.paint.stroke = Color.WHITE;
        circle.paint.stroke_width = 0.08;

        // Animate creation
        await this.play(new Create(circle, { duration: 1500, rate_func: Rate.easeOutCubic() }));

        // Shift position using declarative layout
        await this.play(circle.animate.shift(RIGHT.scale(3)));

        // Create a Square
        const square = new Rect(3.5, 3.5);
        square.paint.fill = new Color(1.0, 0.2, 0.5, 1.0);

        // Morph the Circle into a Square
        await this.play(Morph(circle, square, { duration: 2000 }));

        // Pause for 1 second
        await this.wait(1000);
    }
}

